/**
 * Security headers, download routing, and the legacy update path.
 *
 * The .appinstaller is no longer a committed file: it is generated by
 * `app/api/download/appinstaller/route.ts` from the latest GitHub release, so the release workflow
 * never pushes to `main` and branch protection can stay on.
 *
 * Notes on the CSP:
 * - Next.js injects inline bootstrap/hydration scripts, so `script-src` needs 'unsafe-inline'
 *   unless you move to a nonce-based policy via middleware. A nonce policy forces every route to
 *   be dynamic, which would cost the static generation this site relies on.
 * - Google Fonts is the only third-party origin: the stylesheet comes from fonts.googleapis.com
 *   and the font files from fonts.gstatic.com.
 * - `frame-ancestors 'none'` in the CSP is the modern clickjacking control; X-Frame-Options is
 *   kept for older browsers.
 */
const csp = [
  "default-src 'self'",
  "script-src 'self' 'unsafe-inline'",
  "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
  "font-src 'self' https://fonts.gstatic.com",
  "img-src 'self' data:",
  "connect-src 'self'",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
  "upgrade-insecure-requests"
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Frame-Options", value: "DENY" },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // No feature on this site needs a device permission; deny them outright.
  { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(), payment=(), usb=()" },
  { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
  { key: "Strict-Transport-Security", value: "max-age=63072000; includeSubDomains; preload" }
];

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,

  async headers() {
    return [
      {
        source: "/(.*)",
        headers: securityHeaders
      }
    ];
  },

  async redirects() {
    return [
      // Pretty entry point. 307, not 308: the route may move, and browsers cache 308s forever.
      { source: "/download", destination: "/api/download/appinstaller", permanent: false },
      { source: "/download/appinstaller", destination: "/api/download/appinstaller", permanent: false },
      // The legal pages used to be loose HTML in /public. Permanent: the new paths are the site.
      { source: "/privacy.html", destination: "/privacy", permanent: true },
      { source: "/licence.html", destination: "/licence", permanent: true }
    ];
  },

  async rewrites() {
    return [
      // Installs already on people's machines poll this exact path (it is the Uri baked into
      // every release before this change). Keep it alive by serving the generated feed there
      // instead of redirecting, so the update check never depends on redirect handling.
      { source: "/downloads/nectar.appinstaller", destination: "/api/download/appinstaller" }
    ];
  }
};

export default nextConfig;
